package local.civic.home;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.*;import android.graphics.drawable.Drawable;import android.text.*;import android.view.*;import android.view.inputmethod.InputMethodManager;import android.widget.*;import android.util.LruCache;import java.util.*;
public final class AppPickerActivity extends Activity {
 static final String ROLE="role",TARGET="target";UiKit ui;String role,current;GridView grid;final ArrayList<Entry> all=new ArrayList<>(),visible=new ArrayList<>();final LruCache<String,Drawable> icons=new LruCache<>(48);final Handler main=new Handler(Looper.getMainLooper());final java.util.concurrent.ExecutorService iconLoader=java.util.concurrent.Executors.newSingleThreadExecutor();Adapter adapter;
 static final class Entry{String label,target;Entry(String l,String t){label=l;target=t;}}
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setBackgroundDrawable(new android.graphics.drawable.ColorDrawable(ThemeTokens.get(this).background));getWindow().getDecorView().setSystemUiVisibility(UiFlags.IMMERSIVE);getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_HIDDEN);ui=new UiKit(this);role=getIntent().getStringExtra(ROLE);if(role==null)role="";current=getIntent().getStringExtra(TARGET);if(current==null)current="";LinearLayout root=ui.column();root.setBackgroundColor(ui.t.background);root.setFocusableInTouchMode(true);root.addView(ui.header("Choose app"),new LinearLayout.LayoutParams(-1,ui.dp(56)));EditText search=new EditText(this);search.setSingleLine();search.setHint("Search apps");search.setTextColor(ui.t.textPrimary);search.setHintTextColor(ui.t.textSecondary);search.setTextSize(16);search.setMinHeight(ui.dp(56));root.addView(search);grid=new GridView(this);grid.setNumColumns(5);grid.setVerticalSpacing(ui.dp(8));grid.setHorizontalSpacing(ui.dp(8));grid.setStretchMode(GridView.STRETCH_COLUMN_WIDTH);root.addView(grid,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);root.requestFocus();adapter=new Adapter();grid.setAdapter(adapter);grid.setOnItemClickListener((parent,v,pos,id)->{Intent data=new Intent().putExtra(ROLE,role).putExtra(TARGET,visible.get(pos).target);setResult(RESULT_OK,data);finish();});search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void onTextChanged(CharSequence s,int st,int before,int count){filter(s.toString());}public void afterTextChanged(Editable e){}});
 new Thread(()->{PackageManager pm=getPackageManager();List<ResolveInfo> apps=pm.queryIntentActivities(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER),0);Collections.sort(apps,new ResolveInfo.DisplayNameComparator(pm));ArrayList<Entry> result=new ArrayList<>();result.add(new Entry(role.equals("startup")?"Do not open an app":"Use launcher default",""));for(ResolveInfo r:apps){String target=new ComponentName(r.activityInfo.packageName,r.activityInfo.name).flattenToString();result.add(new Entry(r.loadLabel(pm).toString(),target));}main.post(()->{if(isFinishing()||isDestroyed())return;all.clear();all.addAll(result);filter(search.getText().toString());});}).start();}
 @Override protected void onDestroy(){iconLoader.shutdownNow();main.removeCallbacksAndMessages(null);super.onDestroy();}
 void filter(String q){visible.clear();String term=q.toLowerCase(Locale.getDefault());for(Entry e:all)if(e.target.isEmpty()||e.label.toLowerCase(Locale.getDefault()).contains(term))visible.add(e);adapter.notifyDataSetChanged();}
 final class Adapter extends BaseAdapter{public int getCount(){return visible.size();}public Object getItem(int p){return visible.get(p);}public long getItemId(int p){return p;}public View getView(int pos,View convert,android.view.ViewGroup parent){LinearLayout cell;if(convert instanceof LinearLayout)cell=(LinearLayout)convert;else{cell=ui.column();cell.setGravity(Gravity.CENTER);cell.setMinimumHeight(ui.dp(96));ImageView image=new ImageView(AppPickerActivity.this);image.setId(android.R.id.icon);cell.addView(image,new LinearLayout.LayoutParams(ui.dp(42),ui.dp(42)));TextView title=ui.text("",14,ui.t.textPrimary);title.setId(android.R.id.text1);title.setGravity(Gravity.CENTER);title.setMaxLines(2);cell.addView(title,new LinearLayout.LayoutParams(-1,-2));}Entry e=visible.get(pos);ImageView image=cell.findViewById(android.R.id.icon);image.setTag(e.target);Drawable cached;synchronized(icons){cached=icons.get(e.target);}image.setImageDrawable(cached);if(cached==null&&!e.target.isEmpty()){String target=e.target;iconLoader.execute(()->{try{Drawable d=getPackageManager().getActivityIcon(ComponentName.unflattenFromString(target));synchronized(icons){icons.put(target,d);}main.post(()->{if(!isFinishing()&&!isDestroyed()&&target.equals(image.getTag()))image.setImageDrawable(d);});}catch(Exception ignored){}});}TextView title=cell.findViewById(android.R.id.text1);title.setText(e.label+(e.target.equals(current)?" ✓":""));return cell;}}
}
